// news-image-20261125 — "Sum up 25 November's world news in one image".
//
// A hand-written newspaper renderer: it draws one 1024x1024 image that sums up
// the world news of Wednesday 25 November 2026. The type is real DejaVu Serif:
// the glyph outlines (extracted from the system TTFs) are embedded below as
// flattened polygons and filled by a small scanline rasterizer, so the image
// text looks like ordinary newspaper type — no pixel font anywhere.
//
// Run locally:  mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts
// The program writes entry.png (1024x1024, under 1 MiB) and is deterministic:
// two runs write byte-identical output. No network, standard library only.

import { writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { inflateSync, deflateSync } from 'node:zlib';

// ---------------------------------------------------------------------------
// Embedded DejaVu Serif glyph outlines (regular + bold), zlib+base64 of JSON:
// { regular: {upem, glyphs: {char: {a: advance, c: [[[x,y],...], ...]}}}, bold: {...} }
// Coordinates are integer font units, y-up, curves pre-flattened to polygons.
// ---------------------------------------------------------------------------
const FONT_B64 = "";

type Glyph = { a: number; c: number[][][] };
type Font = { upem: number; glyphs: Record<string, Glyph> };
const FONTS: { regular: Font; bold: Font } = JSON.parse(
  inflateSync(Buffer.from(FONT_B64, 'base64')).toString('utf8'),
);

// ---------------------------------------------------------------------------
// Framebuffer: rendered at 2x and box-downsampled for anti-aliasing.
// All layout coordinates below are in 1024-space; primitives scale by SS.
// ---------------------------------------------------------------------------
const W = 1024;
const H = 1024;
const SS = 2;
const BW = W * SS;
const BH = H * SS;
const buf = new Uint8ClampedArray(BW * BH * 4);

type RGB = [number, number, number];

function putPixel(x: number, y: number, col: RGB, alpha: number): void {
  if (x < 0 || y < 0 || x >= BW || y >= BH) return;
  const i = (y * BW + x) * 4;
  if (alpha >= 1) {
    buf[i] = col[0]; buf[i + 1] = col[1]; buf[i + 2] = col[2]; buf[i + 3] = 255;
  } else {
    buf[i] = Math.round(buf[i] + (col[0] - buf[i]) * alpha);
    buf[i + 1] = Math.round(buf[i + 1] + (col[1] - buf[i + 1]) * alpha);
    buf[i + 2] = Math.round(buf[i + 2] + (col[2] - buf[i + 2]) * alpha);
    buf[i + 3] = 255;
  }
}

// Fill a polygon (points in 1024-space) with the nonzero winding rule.
// An optional clip rectangle (1024-space) keeps scene art inside its panel.
let clipX0 = 0, clipY0 = 0, clipX1 = W, clipY1 = H;
function setClip(x: number, y: number, w: number, h: number): void {
  clipX0 = x; clipY0 = y; clipX1 = x + w; clipY1 = y + h;
}
function clearClip(): void { clipX0 = 0; clipY0 = 0; clipX1 = W; clipY1 = H; }

function fillPoly(pts: number[][], col: RGB, alpha = 1): void {
  if (pts.length < 3) return;
  const p = pts.map(([x, y]) => [x * SS, y * SS] as [number, number]);
  let ymin = Infinity, ymax = -Infinity;
  for (const [, y] of p) { if (y < ymin) ymin = y; if (y > ymax) ymax = y; }
  const y0 = Math.max(Math.floor(clipY0 * SS), Math.floor(ymin));
  const y1 = Math.min(Math.ceil(clipY1 * SS) - 1, Math.ceil(ymax));
  const cx0 = Math.floor(clipX0 * SS), cx1 = Math.ceil(clipX1 * SS) - 1;
  const n = p.length;
  for (let y = y0; y <= y1; y++) {
    const yc = y + 0.5;
    const cross: Array<[number, number]> = [];
    for (let i = 0; i < n; i++) {
      const [x1, yy1] = p[i];
      const [x2, yy2] = p[(i + 1) % n];
      if (yy1 === yy2) continue;
      if ((yc >= yy1 && yc < yy2) || (yc >= yy2 && yc < yy1)) {
        const t = (yc - yy1) / (yy2 - yy1);
        cross.push([x1 + t * (x2 - x1), yy2 > yy1 ? 1 : -1]);
      }
    }
    if (cross.length === 0) continue;
    cross.sort((a, b) => a[0] - b[0]);
    let wind = 0;
    for (let i = 0; i < cross.length - 1; i++) {
      wind += cross[i][1];
      if (wind !== 0) {
        const xa = Math.max(cx0, Math.ceil(cross[i][0] - 0.5));
        const xb = Math.min(cx1, Math.floor(cross[i + 1][0] - 0.5));
        for (let x = xa; x <= xb; x++) putPixel(x, y, col, alpha);
      }
    }
  }
}

function fillRect(x: number, y: number, w: number, h: number, col: RGB, alpha = 1): void {
  fillPoly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], col, alpha);
}

function fillCircle(cx: number, cy: number, r: number, col: RGB, alpha = 1): void {
  const pts: number[][] = [];
  const steps = Math.max(12, Math.floor(r * 1.5));
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
  }
  fillPoly(pts, col, alpha);
}

function strokeLine(x1: number, y1: number, x2: number, y2: number, wdt: number, col: RGB, alpha = 1): void {
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.hypot(dx, dy) || 1;
  const nx = (-dy / len) * (wdt / 2), ny = (dx / len) * (wdt / 2);
  fillPoly([[x1 + nx, y1 + ny], [x2 + nx, y2 + ny], [x2 - nx, y2 - ny], [x1 - nx, y1 - ny]], col, alpha);
}

function strokeRect(x: number, y: number, w: number, h: number, wdt: number, col: RGB, alpha = 1): void {
  fillRect(x, y, w, wdt, col, alpha);
  fillRect(x, y + h - wdt, w, wdt, col, alpha);
  fillRect(x, y, wdt, h, col, alpha);
  fillRect(x + w - wdt, y, wdt, h, col, alpha);
}

function dashLine(x1: number, y1: number, x2: number, y2: number, wdt: number, col: RGB): void {
  const len = Math.hypot(x2 - x1, y2 - y1);
  const seg = 5, gap = 4;
  const steps = Math.floor(len / (seg + gap));
  for (let i = 0; i < steps; i++) {
    const t0 = (i * (seg + gap)) / len;
    const t1 = (i * (seg + gap) + seg) / len;
    strokeLine(x1 + (x2 - x1) * t0, y1 + (y2 - y1) * t0, x1 + (x2 - x1) * t1, y1 + (y2 - y1) * t1, wdt, col);
  }
}

// ---------------------------------------------------------------------------
// Text engine: measure and draw with the embedded serif glyphs.
// ---------------------------------------------------------------------------
function glyphOf(font: Font, ch: string): Glyph | undefined {
  return font.glyphs[ch] ?? font.glyphs['?'];
}

function textWidth(text: string, font: Font, size: number): number {
  const scale = size / font.upem;
  let w = 0;
  for (const ch of text) {
    const g = glyphOf(font, ch);
    w += (g ? g.a : font.upem * 0.5) * scale;
  }
  return w;
}

// Draw one line of text with its baseline at y. Returns the drawn width.
function drawText(text: string, x: number, y: number, font: Font, size: number, col: RGB): number {
  const scale = size / font.upem;
  let pen = x;
  for (const ch of text) {
    const g = glyphOf(font, ch);
    if (!g) { pen += size * 0.5; continue; }
    for (const contour of g.c) {
      const pts = contour.map(([gx, gy]) => [pen + gx * scale, y - gy * scale]);
      fillPoly(pts, col);
    }
    pen += g.a * scale;
  }
  return pen - x;
}

function drawTextC(text: string, cx: number, y: number, font: Font, size: number, col: RGB): void {
  drawText(text, cx - textWidth(text, font, size) / 2, y, font, size, col);
}

// Greedy word wrap; returns the lines that fit maxW (at most maxLines, last
// line ellipsised when the text is cut).
function wrap(text: string, font: Font, size: number, maxW: number, maxLines: number): string[] {
  const words = text.split(' ');
  const lines: string[] = [];
  let cur = '';
  for (const wd of words) {
    const trial = cur ? cur + ' ' + wd : wd;
    if (textWidth(trial, font, size) <= maxW || cur === '') {
      cur = trial;
    } else {
      lines.push(cur);
      cur = wd;
      if (lines.length === maxLines) break;
    }
  }
  if (lines.length < maxLines && cur) lines.push(cur);
  if (lines.length === maxLines) {
    const used = lines.join(' ').split(' ').length;
    if (used < words.length) {
      let last = lines[maxLines - 1];
      while (last.length > 0 && textWidth(last + '\u2026', font, size) > maxW) last = last.slice(0, -1);
      lines[maxLines - 1] = last + '\u2026';
    }
  }
  return lines;
}

// Draw wrapped text block; returns the y just below the block.
function drawBlock(text: string, x: number, y: number, maxW: number, font: Font, size: number, col: RGB, lineH: number, maxLines: number): number {
  const lines = wrap(text, font, size, maxW, maxLines);
  let yy = y;
  for (const ln of lines) {
    drawText(ln, x, yy + size * 0.82, font, size, col);
    yy += lineH;
  }
  return yy;
}

// ---------------------------------------------------------------------------
// PNG encoder: filter-choice per row, zlib level 9, deterministic.
// ---------------------------------------------------------------------------
const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(data: Buffer): number {
  let c = 0xffffffff;
  for (let i = 0; i < data.length; i++) c = CRC_TABLE[(c ^ data[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type: string, data: Buffer): Buffer {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([len, body, crc]);
}

function paeth(a: number, b: number, c: number): number {
  const p = a + b - c;
  const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
  return pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
}

function encodePNG(rgba: Uint8ClampedArray, w: number, h: number): Buffer {
  const stride = w * 4;
  const raw = Buffer.alloc((stride + 1) * h);
  const cand = Buffer.alloc(stride);
  for (let y = 0; y < h; y++) {
    const rowOff = y * stride;
    const prevOff = (y - 1) * stride;
    let bestType = 0;
    let bestScore = Infinity;
    let bestRow: Buffer | null = null;
    for (let type = 0; type <= 4; type++) {
      let score = 0;
      for (let i = 0; i < stride; i++) {
        const cur = rgba[rowOff + i];
        const left = i >= 4 ? rgba[rowOff + i - 4] : 0;
        const up = y > 0 ? rgba[prevOff + i] : 0;
        const upLeft = y > 0 && i >= 4 ? rgba[prevOff + i - 4] : 0;
        let v: number;
        if (type === 0) v = cur;
        else if (type === 1) v = cur - left;
        else if (type === 2) v = cur - up;
        else if (type === 3) v = cur - ((left + up) >> 1);
        else v = cur - paeth(left, up, upLeft);
        cand[i] = v & 0xff;
        score += Math.abs(v < 128 ? v : v - 256);
      }
      if (score < bestScore) {
        bestScore = score;
        bestType = type;
        bestRow = Buffer.from(cand);
      }
    }
    raw[y * (stride + 1)] = bestType;
    bestRow!.copy(raw, y * (stride + 1) + 1);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8;  // bit depth
  ihdr[9] = 6;  // RGBA
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

// Box-downsample the 2x buffer to the final 1024x1024 image.
function downsample(): Uint8ClampedArray {
  const out = new Uint8ClampedArray(W * H * 4);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const oi = (y * W + x) * 4;
      for (let ch = 0; ch < 4; ch++) {
        const a = buf[((y * 2) * BW + x * 2) * 4 + ch];
        const b = buf[((y * 2) * BW + x * 2 + 1) * 4 + ch];
        const c = buf[((y * 2 + 1) * BW + x * 2) * 4 + ch];
        const d = buf[((y * 2 + 1) * BW + x * 2 + 1) * 4 + ch];
        out[oi + ch] = Math.round((a + b + c + d) / 4);
      }
    }
  }
  return out;
}

