// ---------------------------------------------------------------------------
// Small vector scenes for the lead and card illustrations. Flat shapes only:
// they read at a glance and keep the PNG small.
// ---------------------------------------------------------------------------
function sceneRefinery(x: number, y: number, w: number, h: number): void {
  fillRect(x, y, w, h, [214, 196, 160]);            // desert sky
  fillRect(x, y + h * 0.72, w, h * 0.28, [188, 158, 112]); // ground
  fillCircle(x + w * 0.86, y + h * 0.2, h * 0.11, [240, 196, 90]); // sun
  const gy = y + h * 0.72;
  // storage tanks
  for (const tx of [0.08, 0.24, 0.40]) {
    fillRect(x + w * tx, gy - h * 0.3, w * 0.13, h * 0.3, [236, 232, 222]);
    fillCircle(x + w * (tx + 0.065), gy - h * 0.3, w * 0.065, [236, 232, 222]);
    strokeRect(x + w * tx, gy - h * 0.3, w * 0.13, h * 0.3, 1.2, FAINT);
  }
  // fractionation towers
  for (const tx of [0.58, 0.68]) {
    fillRect(x + w * tx, gy - h * 0.58, w * 0.055, h * 0.58, [200, 196, 186]);
    for (let i = 0; i < 4; i++) fillRect(x + w * (tx - 0.012), gy - h * (0.16 + i * 0.12), w * 0.08, 2, FAINT);
  }
  // flare stack + flame
  fillRect(x + w * 0.79, gy - h * 0.66, 3, h * 0.66, [120, 112, 100]);
  fillPoly([[x + w * 0.79, gy - h * 0.66], [x + w * 0.83, gy - h * 0.8], [x + w * 0.81, gy - h * 0.66]], [232, 120, 40]);
  // drone + dashed path
  const dx = x + w * 0.16, dy = y + h * 0.18;
  dashLine(x + w * 0.02, y + h * 0.3, dx - 8, dy + 4, 1.4, RED);
  fillRect(dx - 7, dy - 2, 14, 4, INK);
  fillCircle(dx - 9, dy - 4, 3.4, INK); fillCircle(dx + 9, dy - 4, 3.4, INK);
  fillCircle(dx - 9, dy + 4, 3.4, INK); fillCircle(dx + 9, dy + 4, 3.4, INK);
}

function sceneStation(x: number, y: number, w: number, h: number): void {
  fillRect(x, y, w, h, [16, 26, 52]);               // space
  const stars: Array<[number, number]> = [[0.08, 0.15], [0.2, 0.4], [0.35, 0.12], [0.55, 0.3], [0.7, 0.1], [0.88, 0.35], [0.62, 0.55], [0.15, 0.65], [0.95, 0.6], [0.45, 0.5]];
  for (const [sx, sy] of stars) fillCircle(x + w * sx, y + h * sy, 1.3, [230, 236, 250]);
  fillCircle(x + w * 0.5, y + h * 1.5, h * 0.82, [52, 110, 180]); // Earth limb
  // station: truss, modules, solar wings
  const cy = y + h * 0.34;
  fillRect(x + w * 0.06, cy - 1.5, w * 0.88, 3, [190, 196, 206]);
  fillRect(x + w * 0.40, cy - h * 0.09, w * 0.2, h * 0.18, [226, 230, 236]);
  fillRect(x + w * 0.30, cy - h * 0.06, w * 0.1, h * 0.12, [200, 206, 216]);
  fillRect(x + w * 0.60, cy - h * 0.06, w * 0.1, h * 0.12, [200, 206, 216]);
  for (const px of [0.08, 0.76]) {
    fillRect(x + w * px, cy - h * 0.16, w * 0.16, h * 0.32, [44, 84, 168]);
    for (let i = 1; i < 4; i++) fillRect(x + w * (px + i * 0.04), cy - h * 0.16, 1, h * 0.32, [120, 160, 220]);
    fillRect(x + w * px, cy - 0.8, w * 0.16, 1.6, [120, 160, 220]);
  }
  // approaching capsule + flame
  const rx = x + w * 0.5, ry = y + h * 0.68;
  fillPoly([[rx - 7, ry], [rx + 7, ry], [rx + 4, ry + h * 0.16], [rx - 4, ry + h * 0.16]], [236, 238, 240]);
  fillPoly([[rx - 4, ry + h * 0.16], [rx + 4, ry + h * 0.16], [rx, ry + h * 0.3]], [240, 150, 50]);
  dashLine(rx, ry - 2, rx, cy + h * 0.1, 1.2, [170, 200, 240]);
}

function sceneChart(x: number, y: number, w: number, h: number): void {
  fillRect(x, y, w, h, [244, 241, 233]);
  const ax = x + w * 0.08, ay = y + h * 0.82, aw = w * 0.84, ah = h * 0.66;
  for (let i = 0; i <= 3; i++) {
    const gy = ay - (ah * i) / 3;
    strokeLine(ax, gy, ax + aw, gy, 0.8, [205, 198, 184]);
  }
  // descending bars
  const bars = [0.92, 0.8, 0.68, 0.55, 0.42, 0.3];
  bars.forEach((b, i) => {
    const bx = ax + (aw * i) / bars.length + 3;
    const bw = aw / bars.length - 7;
    fillRect(bx, ay - ah * b, bw, ah * b, [214, 120, 110]);
  });
  // falling line + arrow
  const pts = bars.map((b, i) => [ax + (aw * (i + 0.5)) / bars.length, ay - ah * b - 4]);
  for (let i = 0; i < pts.length - 1; i++) strokeLine(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], 2.6, RED);
  const [lx, ly] = pts[pts.length - 1];
  fillPoly([[lx, ly], [lx - 9, ly - 2], [lx - 3, ly + 8]], RED);
  strokeLine(ax, ay, ax + aw, ay, 1.6, INK);
  strokeLine(ax, ay - ah, ax, ay, 1.6, INK);
  // chip icon
  const cx = x + w * 0.8, cyy = y + h * 0.1, cs = h * 0.2;
  fillRect(cx, cyy, cs, cs, NAVY);
  for (let i = 0; i < 4; i++) {
    fillRect(cx + 2 + i * (cs / 4), cyy - 3, 1.6, 3, NAVY);
    fillRect(cx + 2 + i * (cs / 4), cyy + cs, 1.6, 3, NAVY);
    fillRect(cx - 3, cyy + 2 + i * (cs / 4), 3, 1.6, NAVY);
    fillRect(cx + cs, cyy + 2 + i * (cs / 4), 3, 1.6, NAVY);
  }
  fillRect(cx + cs * 0.28, cyy + cs * 0.28, cs * 0.44, cs * 0.44, [150, 180, 220]);
}

function sceneMini(kind: string, x: number, y: number, w: number, h: number): void {
  const cx = x + w / 2, cy = y + h / 2;
  if (kind === 'report') {
    fillRect(x + 6, y + 8, w - 12, h - 16, [252, 250, 244]);
    strokeRect(x + 6, y + 8, w - 12, h - 16, 1.2, FAINT);
    for (let i = 0; i < 4; i++) fillRect(x + 11, y + 14 + i * 6, w - 22 - (i % 2) * 8, 2.4, [150, 144, 132]);
    fillRect(x + 11, y + h - 26, 7, 12, RED); fillRect(x + 20, y + h - 21, 7, 7, [214, 120, 110]); fillRect(x + 29, y + h - 17, 7, 3, [230, 170, 150]);
  } else if (kind === 'treaty') {
    fillRect(x + 8, y + 8, w - 16, h - 16, [252, 250, 244]);
    strokeRect(x + 8, y + 8, w - 16, h - 16, 1.2, FAINT);
    for (let i = 0; i < 3; i++) fillRect(x + 13, y + 14 + i * 6, w - 26, 2.4, [150, 144, 132]);
    fillCircle(cx, y + h - 20, 8, RED);
    fillPoly([[cx - 5, y + h - 14], [cx - 2, y + h - 14], [cx - 6, y + h - 5]], RED);
    fillPoly([[cx + 2, y + h - 14], [cx + 5, y + h - 14], [cx + 6, y + h - 5]], RED);
  } else if (kind === 'expel') {
    fillRect(x + 10, y + h - 34, w - 20, 26, [196, 188, 170]);
    fillPoly([[x + 8, y + h - 34], [cx, y + h - 48], [x + w - 8, y + h - 34]], [120, 112, 100]);
    fillRect(cx - 5, y + h - 26, 10, 18, [90, 80, 66]);
    strokeLine(x + w - 12, cy - 6, x + w - 2, cy - 6, 2.4, RED);
    fillPoly([[x + w - 2, cy - 6], [x + w - 9, cy - 10], [x + w - 9, cy - 2]], RED);
  } else if (kind === 'factory') {
    fillRect(x + 8, y + h - 26, w - 16, 18, [170, 164, 150]);
    fillPoly([[x + 8, y + h - 26], [x + 20, y + h - 36], [x + 20, y + h - 26]], [120, 112, 100]);
    fillPoly([[x + 20, y + h - 26], [x + 32, y + h - 36], [x + 32, y + h - 26]], [120, 112, 100]);
    fillRect(x + w - 18, y + h - 48, 7, 22, [150, 144, 132]);
    fillCircle(x + w - 14, y + h - 54, 5, [210, 204, 192]);
    fillCircle(x + 16, y + 14, 8, [240, 196, 90]);
    strokeLine(x + 16, y + 18, x + 16, y + 10, 2, [146, 110, 24]);
    fillPoly([[x + 16, y + 8], [x + 12, y + 14], [x + 20, y + 14]], [146, 110, 24]);
  } else if (kind === 'shield') {
    fillPoly([[cx - 13, y + 12], [cx + 13, y + 12], [cx + 13, cy], [cx, y + h - 10], [cx - 13, cy]], NAVY);
    fillCircle(cx, cy - 4, 6, [240, 196, 90]);
    fillRect(cx - 1.5, cy - 12, 3, 16, [240, 196, 90]);
  } else if (kind === 'placards') {
    for (const [px, py, c] of [[0.22, 0.34, RED], [0.52, 0.22, NAVY], [0.78, 0.38, TEAL]] as Array<[number, number, RGB]>) {
      const gx = x + w * px, gy = y + h * py;
      fillRect(gx - 9, gy - 8, 18, 12, [252, 250, 244]);
      strokeRect(gx - 9, gy - 8, 18, 12, 1.2, c);
      fillRect(gx - 6, gy - 4, 12, 2, c);
      fillRect(gx - 6, gy + 0, 9, 2, c);
      strokeLine(gx, gy + 4, gx, gy + 16, 1.8, [90, 80, 66]);
    }
    for (let i = 0; i < 5; i++) fillCircle(x + 10 + i * ((w - 20) / 4), y + h - 12, 4, [90, 80, 66]);
  } else if (kind === 'mine') {
    fillRect(x, y + 10, w, 8, [150, 128, 96]);
    fillRect(cx - 7, y + 18, 14, h - 26, [52, 44, 36]);
    fillRect(cx - 13, y + 8, 26, 4, [110, 94, 70]);
    dashLine(cx, y + 18, cx, y + h - 22, 1.4, [230, 220, 190]);
    fillCircle(cx, y + h - 16, 5, [250, 220, 120]);
    fillCircle(cx, y + h - 16, 9, [250, 220, 120], 0.35);
  } else if (kind === 'ball') {
    fillRect(x + 8, y + h - 16, w - 16, 3, [60, 140, 80]);
    strokeLine(x + 12, y + 14, x + 12, y + h - 16, 2.2, [240, 240, 240]);
    strokeLine(x + w - 12, y + 14, x + w - 12, y + h - 16, 2.2, [240, 240, 240]);
    strokeLine(x + 12, y + 14, x + w - 12, y + 14, 2.2, [240, 240, 240]);
    fillCircle(cx, cy + 8, 12, [252, 252, 252]);
    fillCircle(cx, cy + 8, 4, INK);
    fillCircle(cx - 8, cy + 3, 2.6, INK); fillCircle(cx + 8, cy + 3, 2.6, INK);
    fillCircle(cx - 5, cy + 15, 2.6, INK); fillCircle(cx + 5, cy + 15, 2.6, INK);
  }
}

