function drawMap(x: number, y: number, w: number, h: number, stories: Story[]): void {
  fillRect(x, y, w, h, SEA);
  const px = (lon: number) => x + ((lon + 180) / 360) * w;
  const py = (lat: number) => y + ((78 - lat) / 136) * h;
  for (const poly of CONTINENTS) {
    fillPoly(poly.map(([lon, lat]) => [px(lon), py(lat)]), LAND);
  }
  for (const s of stories) {
    const cx = px(s.lon), cy = py(s.lat);
    fillCircle(cx, cy, 7, RED);
    fillCircle(cx, cy, 7, [255, 255, 255], 0.0);
    const label = String(s.n);
    const tw = textWidth(label, FONTS.bold, 8);
    drawText(label, cx - tw / 2, cy + 2.8, FONTS.bold, 8, [255, 255, 255]);
  }
}

// ---------------------------------------------------------------------------
// Layout: a one-page broadsheet for Wednesday 25 November 2026.
// ---------------------------------------------------------------------------
const M = 18;               // side margin
const CW = W - M * 2;       // content width
const REG = FONTS.regular;
const BLD = FONTS.bold;

function sectionHeader(text: string, x: number, y: number, w: number): void {
  drawText(text, x, y + 11, BLD, 12.5, INK);
  fillRect(x, y + 15, w, 1.6, RULE);
}

function drawBadge(x: number, y: number, badge: Badge, src: string): void {
  const label = badge;
  const tw = textWidth(label, BLD, 7.5);
  fillRect(x, y, tw + 8, 11, BADGE_COL[badge]);
  drawText(label, x + 4, y + 8.4, BLD, 7.5, [255, 255, 255]);
  drawText(src, x + tw + 13, y + 8.4, REG, 8.5, FAINT);
}

function drawMasthead(): void {
  drawTextC('THE WORLD', W / 2, 58, BLD, 54, INK);
  drawTextC('Wednesday 25 November 2026', W / 2, 84, BLD, 19, INK);
  drawTextC('35 STORIES \u00b7 7 REGIONS \u00b7 13 FIELDS \u2014 EVERY ONE DATED WEDNESDAY 25 NOV', W / 2, 100, REG, 11, FAINT);
  fillRect(M, 106, CW, 2.2, RULE);
}

function drawStats(): void {
  const stats: Array<[string, string, RGB]> = [
    ['\u22124.59%', 'TAIEX CLOSE', RED],
    ['\u22125.7%', 'KOSPI CLOSE', RED],
    ['5,186.80', 'IHSG (\u22121.05%)', INK],
    ['18,310', 'USD / IDR', INK],
    ['$90.96', 'BRENT / BBL', INK],
    ['26', 'MINERS TRAPPED', RED],
  ];
  const y = 112;
  const cw = CW / stats.length;
  stats.forEach(([val, label, col], i) => {
    const cx = M + cw * i + cw / 2;
    drawTextC(val, cx, y + 22, BLD, 20, col);
    drawTextC(label, cx, y + 36, REG, 8.5, FAINT);
    if (i > 0) fillRect(M + cw * i, y + 4, 1, 36, [190, 182, 166]);
  });
  fillRect(M, 152, CW, 1.4, RULE);
}

function drawLeads(): void {
  sectionHeader('TOP STORIES', M, 158, CW);
  const y = 178;
  const gap = 10;
  const cw = (CW - gap * 2) / 3;
  const ch = 196;
  LEADS.forEach((s, i) => {
    const x = M + i * (cw + gap);
    fillRect(x, y, cw, ch, [252, 250, 244]);
    strokeRect(x, y, cw, ch, 1.2, [170, 160, 142]);
    setClip(x + 4, y + 4, cw - 8, 88);
    if (s.scene === 'refinery') sceneRefinery(x + 4, y + 4, cw - 8, 88);
    else if (s.scene === 'station') sceneStation(x + 4, y + 4, cw - 8, 88);
    else sceneChart(x + 4, y + 4, cw - 8, 88);
    clearClip();
    const num = String(s.n);
    fillCircle(x + 13, y + 13, 9, RED);
    drawText(num, x + 13 - textWidth(num, BLD, 10) / 2, y + 16.6, BLD, 10, [255, 255, 255]);
    let yy = y + 98;
    yy = drawBlock(s.h, x + 8, yy, cw - 16, BLD, 15.5, INK, 18, 2);
    yy = drawBlock(s.s ?? '', x + 8, yy + 1, cw - 16, REG, 10, [52, 48, 42], 12.5, 3);
    drawBadge(x + 8, y + ch - 16, s.b, s.src);
  });
}

function drawCards(): void {
  sectionHeader('MORE OF THE DAY', M, 380, CW);
  const y = 400;
  const gap = 7;
  const cw = (CW - gap * 3) / 4;
  const ch = 88;
  CARDS.forEach((s, i) => {
    const x = M + (i % 4) * (cw + gap);
    const yy = y + Math.floor(i / 4) * (ch + gap);
    fillRect(x, yy, cw, ch, [252, 250, 244]);
    strokeRect(x, yy, cw, ch, 1, [170, 160, 142]);
    setClip(x + 4, yy + 4, 56, ch - 8);
    sceneMini(s.scene ?? '', x + 4, yy + 4, 56, ch - 8);
    clearClip();
    const tx = x + 64;
    const tw = cw - 70;
    drawText(String(s.n) + '.', tx, yy + 13, BLD, 10, RED);
    const numW = textWidth(String(s.n) + '. ', BLD, 10);
    let ty = drawBlock(s.h, tx + numW, yy + 2, tw - numW, BLD, 11, INK, 13, 2);
    ty = drawBlock(s.s ?? '', tx, ty + 1, tw, REG, 8.6, [52, 48, 42], 10.6, 3);
    drawBadge(tx, yy + ch - 15, s.b, s.src);
  });
}

function drawBriefs(x: number, y: number, w: number): void {
  sectionHeader('ALSO ON WEDNESDAY', x, y, w);
  const top = y + 22;
  const colW = (w - 10) / 2;
  const rowH = 21.5;
  BRIEFS.forEach((s, i) => {
    const col = Math.floor(i / 12);
    const row = i % 12;
    const bx = x + col * (colW + 10);
    const by = top + row * rowH;
    drawText(String(s.n) + '.', bx, by + 9, BLD, 9, RED);
    const numW = textWidth(String(s.n) + '. ', BLD, 9);
    const lines = wrap(s.h, BLD, 9.3, colW - numW, 1);
    drawText(lines[0] ?? '', bx + numW, by + 9, BLD, 9.3, INK);
    // mini badge chip + source on the second line
    const tw = textWidth(s.b, BLD, 6.2);
    fillRect(bx + numW, by + 11.5, tw + 5, 8.6, BADGE_COL[s.b]);
    drawText(s.b, bx + numW + 2.5, by + 18.2, BLD, 6.2, [255, 255, 255]);
    drawText(s.src, bx + numW + tw + 9, by + 18.2, REG, 7.6, FAINT);
  });
}

function drawTimeline(x: number, y: number, w: number): void {
  sectionHeader('THE DAY IN UTC', x, y, w);
  const rows: Array<[string, string]> = [
    ['00:18', 'Shenzhou-24 lifts off from Jiuquan'],
    ['00:41', 'Australia\u2013Solomon Islands treaty signed'],
    ['03:56', 'Shenzhou-24 docks at Tiangong'],
    ['05:44', 'Malaysia\u2019s MCMC sues Google (RM600m)'],
    ['06:00', 'Jakarta students rally at Istana'],
    ['06:41', 'Stuart Russell warns on AI risk (NDTV)'],
    ['07:35', 'IHSG closes at 5,186.80'],
    ['08:19', 'STOXX 600 at 636.01 (+0.5%)'],
    ['18:45', 'ESA Hera Dimorphos images due'],
  ];
  let yy = y + 24;
  for (const [t, text] of rows) {
    drawText(t, x, yy + 9, BLD, 9.5, NAVY);
    drawText(text, x + 38, yy + 9, REG, 9.5, INK);
    yy += 16.5;
  }
}

function drawDateCheck(x: number, y: number, w: number): void {
  fillRect(x, y, w, 132, [238, 230, 210]);
  strokeRect(x, y, w, 132, 1.2, [170, 160, 142]);
  drawText('DATE CHECK \u2014 NOT 25 NOV', x + 8, y + 16, BLD, 11.5, RED);
  drawText('Big stories checked and excluded:', x + 8, y + 30, REG, 8.6, FAINT);
  const lines = [
    'Huawei convicted in US \u2014 Tue 24 Nov',
    'Nvidia Huang \u201cviolated code of conduct\u201d \u2014 24 Nov',
    'US consumer confidence 103.3 \u2014 24 Nov',
    'Jensen Huang returns to Nvidia \u2014 Mon 23 Nov',
    'Cikande candy factory fire \u2014 Sat 21 Nov',
    'COP31 collapse, Antalya \u2014 Sun 22 Nov',
    'ICJ Myanmar genocide ruling \u2014 19 Nov',
    'Ukraine sinks corvette at Benghazi \u2014 22 Nov',
  ];
  let yy = y + 36;
  for (const ln of lines) {
    drawText('\u00d7 ' + ln, x + 8, yy + 8, REG, 8.8, [52, 48, 42]);
    yy += 11.8;
  }
}

function drawFooter(): void {
  const y = 998;
  fillRect(M, y, CW, 1.2, RULE);
  let x = M;
  const legend: Array<[Badge, string]> = [
    ['CONFIRMED', '2+ outlets / primary data'],
    ['OFFICIAL', 'agency statement'],
    ['REPORTED', 'major outlet report'],
    ['CLAIM', 'attributed, unverified'],
  ];
  for (const [b, def] of legend) {
    const tw = textWidth(b, BLD, 7);
    fillRect(x, y + 5, tw + 7, 10.5, BADGE_COL[b]);
    drawText(b, x + 3.5, y + 13, BLD, 7, [255, 255, 255]);
    x += tw + 11;
    drawText(def, x, y + 13, REG, 8, FAINT);
    x += textWidth(def, REG, 8) + 14;
  }
  const note = 'Every story dated Wednesday 25 November 2026 \u00b7 sources named';
  drawText(note, W - M - textWidth(note, REG, 8), y + 13, REG, 8, FAINT);
}

function render(): void {
  fillRect(0, 0, W, H, PAPER);
  drawMasthead();
  drawStats();
  drawLeads();
  drawCards();
  // bottom band: map + timeline (left), briefs + date check (right)
  sectionHeader('WHERE IT HAPPENED', M, 590, 542);
  setClip(M, 612, 542, 180);
  drawMap(M, 612, 542, 180, [...LEADS, ...CARDS, ...BRIEFS]);
  clearClip();
  drawTimeline(M, 800, 542);
  drawBriefs(572, 590, 434);
  drawDateCheck(572, 864, 434);
  drawFooter();
}

// ---------------------------------------------------------------------------
render();
const png = encodePNG(downsample(), W, H);
const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'entry.png'), png);
console.log('wrote entry.png', png.length, 'bytes');
